style.css:
@-moz-document domain("remanga.org") {
/* === УСТАНОВКА ФОНА === */
    :root {
        --custom-bg: url('https://i.gifer.com/xK.gif');
    }

    html, body {
        height: 100%;
        margin: 0;
        padding: 0;
        overflow: auto;
        background: var(--custom-bg) no-repeat center center fixed;
        background-size: cover;
        color: #ffffff !important; /* Белый цвет текста */
    }

    /* Полупрозрачный фон у основного блока */
    #reader {
        background: rgba(21, 21, 21, 0.5) !important;
        border-left: 1px solid #797979;
        border-right: 1px solid #797979;
    }

    /* Оформление карточек */
    .card {
        background-color: #232529;
        border: 1px solid rgb(121, 121, 121) !important;
    }
    .card-title {
        background-color: rgb(35, 37, 41) !important;
        color: #ffffff !important;
    }

    /* Убираем фон у ключевых элементов */
    .z-\[2\] > .flex {
        background: transparent !important;
        box-shadow: none !important;
    }

    /* Создаём дополнительный слой для GIF */
    body::before {
        content: '';
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        z-index: -1;
        background: var(--custom-bg) no-repeat center center fixed;
        background-size: cover;
    }

    /* Навигация */
    .navbar-nav > .nav-item:hover, .navbar-collapse > .nav-item:hover {
        background-color: #34449e !important;
    }
    .dropdown-item:focus {
        background: #c1c1c1;
        color: black !important;
    }

    /* Кнопки */
    .btn-dark:hover {
        background-color: #454b50;
    }
    .btn-outline-dark {
        color: #ffffff !important;
    }

    /* Окна */
    .modal-content {
        background-color: rgb(35, 37, 41);
    }
    .popover-header {
        background-color: inherit;
    }
    .popover {
        background-color: #32343a;
    }

    /* Уведомления */
    .notif.row.unread {
        background-color: #232529;
    }

    /* Ссылки */
    a {
        color: #ffffff !important;
    }
    a:hover {
        color: #FF5722 !important;
    }

    /* Исправление стилей для nth-child */
    [class*="nth-child"] {
        all: unset !important;
        display: revert !important;
    }

    /* Скроллбар */
    ::-webkit-scrollbar {
        width: 13px;
    }
    ::-webkit-scrollbar-track {
        background-color: #32312e;
        box-shadow: 0px 0px 3px #000 inset;
    }
    ::-webkit-scrollbar-thumb {
        border-radius: 5px;
        background-color: #ffffff;
        box-shadow: 0px 1px 1px #fff inset;
    }
    ::-webkit-scrollbar-thumb:hover {
        background-color: #cccccc;
    }
}
